1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const ITEM_BASE_PREMIUM: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	};
16	
17	type Item = { type: string };
18	
19	type Step = { op: string; items: Item[] };
20	
21	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
22	
23	const COMPONENT_BLOCK_SIZE = 3;
24	
25	// Only forced so far by a policy consisting of exactly one rune block, so this
26	// is the premium of the whole policy rather than of a single block.
27	const ALL_ONE_COMPONENT_BLOCK_BASE_PREMIUM = 60;
28	
29	const policyBasePremium = (items: Item[]): number => {
30	  const components = items.filter((item) => item.type === "rune");
31	  if (components.length === COMPONENT_BLOCK_SIZE)
32	    return ALL_ONE_COMPONENT_BLOCK_BASE_PREMIUM;
33	
34	  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
35	};
36	
37	const quoteStep = (step: Step): QuoteResult => {
38	  const basePremium = policyBasePremium(step.items);
39	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
40	  return {
41	    premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
42	  };
43	};
44	
45	export const runScenario = (scenario: Scenario): ScenarioResults => ({
46	  results: scenario.steps.map(quoteStep),
47	});
