const BLOCK_SIZE = 3;

// Forced so far only by a policy that is nothing but one rune block, so this is
// the premium of the whole policy, not yet of a block within a larger policy.
const THREE_RUNE_BLOCK_BASE_PREMIUM = 60;

const isThreeRuneBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");

const policyBasePremium = (items: Item[]): number => {
  if (isThreeRuneBlock(items)) return THREE_RUNE_BLOCK_BASE_PREMIUM;

  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
};
